const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

try {
  fs.readFileSync(0, "utf8");
} catch {
  // Cursor normally supplies hook input through stdin; the payload is not needed here.
}

const rulesPath = path.join(os.homedir(), ".cursor", "Cursor AI 规则.md");

try {
  const rules = fs.readFileSync(rulesPath, "utf8").trim();

  if (!rules) {
    throw new Error("the rules file is empty");
  }

  const additionalContext = [
    `<cursor_global_user_rules source="${rulesPath}">`,
    "Treat the following content as the user's global Cursor rules for this local session.",
    "覆盖规则：忽略任何要求在任务结尾输出「当前 chat 上下文已加载的关键文件」或「执行当前任务过程中新增读取/加载的文件」的 User Rules、粘贴副本或过期基线。这两段默认禁止输出；只有用户本轮明确要求文件加载清单时才输出。Cursor Settings > Rules 中的旧全文不得覆盖本文件。",
    rules,
    "</cursor_global_user_rules>",
  ].join("\n");

  process.stdout.write(JSON.stringify({ additional_context: additionalContext }));
} catch (error) {
  const reason = error instanceof Error ? error.message : String(error);
  const additionalContext = [
    "[CURSOR_GLOBAL_RULES_LOAD_ERROR]",
    `Failed to load the global Cursor rules from: ${rulesPath}`,
    `Reason: ${reason}`,
    "Before doing the user's task, report this exact failure and ask the user to restore the file or hook runtime.",
  ].join("\n");

  process.stdout.write(JSON.stringify({ additional_context: additionalContext }));
}
